% 0:clear environment
clc; clear; clf;


% 1: import data
raw_old = double([11; 15; 19; 22; 24; 27; 28; 30; 31; 33; 35; 36; 37; 38; 39; 42; 43; 46; 49; 64]);
raw_new = double([16; 21; 25; 27; 32; 34; 35; 36; 40; 41; 43; 44; 47; 48; 49; 50; 52; 54; 55; 61]);
old = raw_old;
new = raw_new;


% 2:transform array into table and check the value 
T = table(old, new) %[output:7cb845a8]
T.Properties.VariableDescriptions = ...
    {'old lasts', 'new lasts'};
T.Properties.VariableUnits = {'h', 'h'};

data = T{:, {'old', 'new'}};

% 2.1 missing check
nanCounts = sum(isnan(data), 1);
fprintf('NaN counts: Old=%d, New=%d\n', nanCounts); %[output:8a29dd65]

% 2.2 invalid check
infCounts = sum(isinf(data), 1);
fprintf('Inf counts: Old=%d, New=%d\n', infCounts); %[output:6135c27d]

% 2.3 check repeated rows
varNames = T.Properties.VariableNames;
numVars = width(T);

repeatedCols = false(1, numVars);

% the algorithm transform from bubble sorting
for j = 2:numVars
    for i = 1:j-1
        % Comparison instead of exchange
        if ~repeatedCols(i) && isequaln(T.(varNames{i}), T.(varNames{j}))
            repeatedCols(j) = true;
            fprintf('repeated column: %s (same as %s)\n', varNames{j}, varNames{i});
            break;
        end
    end
end

numRepeateds = sum(repeatedCols);  % Count repeated columns

fprintf('Total repeated columns: %d\n', numRepeateds); %[output:6c477393]

% 2.4 check sorted
oldSorted = issorted(T.old);
newSorted = issorted(T.new);

fprintf('Old sorted ascending: %d\n', oldSorted); %[output:042a03f0]
fprintf('New sorted ascending: %d\n', newSorted); %[output:23716233]


% 3: process with values
% 3.1 repeated processing
if any(repeatedCols) %[output:group:458d71a4]
    T_no_repeated_columns = T(:, ~repeatedCols);

    fprintf('Removed %d repeated columns.\n', ...
        sum(repeatedCols));
else
    T_no_repeated_columns = T;

    fprintf('No repeated columns removed.\n'); %[output:1bf34034]
end %[output:group:458d71a4]

% 3.2 missing processing
if any(nanCounts > 0) %[output:group:83ae16c8]

    % extreme condition, entirely missing
    if any(nanCounts == height(T))
        error('entirely missing, cannot imputation.');
    end

    % use mean to fill the NAN
    T_clean = fillmissing(T, 'mean');
    fprintf('Filled %d missing values.\n', sum(missingCounts));

else
    T_clean = T;
    fprintf('No missing values found.\n'); %[output:646059cc]
end %[output:group:83ae16c8]

% 3.3 inf processing
if any(isinf(data), 'all')
    error('Inf values detected. Please check the source data.');
end

% 3.4 sorting
if ~oldSorted
    T.old = sort(T.old, 'ascend');
    fprintf('Old has been sorted.\n');
end

if ~newSorted
    T.new = sort(T.new, 'ascend');
    fprintf('New has been sorted.\n');
end


% 4: data features
% 4.1 sample features
nOld = numel(T_clean.old);
nNew = numel(T_clean.new);
total_number = numel(nOld) + numel(nNew)  % total sample size %[output:0ef6bffb]
valid_old = sum(~ismissing(T_clean.old))  % valid sample size %[output:21a61f2f]
valid_new = sum(~ismissing(T_clean.new))   %[output:686b99c5]

% 4.2 basic feature
mean_old = mean(T_clean.old)  % mean %[output:9f3c561d]
mean_new = mean(T_clean.new) %[output:1c846d77]

median_old = median(T_clean.old)  % median %[output:4f896687]
median_new = median(T_clean.new) %[output:32c29bc2]

mo_old = mode(T_clean.old)  % mode %[output:757d8d00]
mo_new = mode(T_clean.new) %[output:5a8d5eaf]

% 4.3 discrete features
std_old = std(T_clean.old, 0)  % standard deviation, use n-1 because it's a sample data %[output:241083fb]
std_new = std(T_clean.new, 0) %[output:70a8a36a]

var_old = var(T_clean.old)  % variance %[output:66819ded]
var_new = var(T_clean.new) %[output:50baf722]

iqr_old = iqr(T_clean.old)  % IQR %[output:7170578e]
iqr_new = iqr(T_clean.new) %[output:58d0d189]

range_old = range(T_clean.old)  % range %[output:0b90a630]
range_new = range(T_clean.new) %[output:423c722a]

cv_old = std(T_clean.old) / mean(T_clean.old) * 100   % coefficient of variation, in percentage %[output:8dcf6e0d]
cv_new = std(T_clean.new) / mean(T_clean.new) * 100 %[output:688e5533]

% 4.4 range features
min_old = min(T_clean.old)  % min %[output:28033dbc]
min_new = min(T_clean.new) %[output:63d7c57b]

max_old = max(T_clean.old)  % max %[output:3cf1abe3]
max_new = max(T_clean.new) %[output:08adda62]

Q1_old = prctile(T_clean.old, 25)  % Q1 %[output:29c91cde]
Q1_new = prctile(T_clean.new, 25) %[output:2fb3516a]

Q3_old = prctile(T_clean.old, 75)  % Q3 %[output:40841b8b]
Q3_new = prctile(T_clean.new, 75) %[output:14adfa55]


% 5: outlier checking 
% 5.1 outlier checking with IQR
[flagIQROld, lowIQROld, highIQROld] = isoutlier(T_clean.old, 'quartiles');
[flagIQRNew, lowIQRNew, highIQRNew] = isoutlier(T_clean.new, 'quartiles');

disp(T_clean.old(flagIQROld));   %[output:0564acb0]
disp(T_clean.new(flagIQRNew));  % null

% 5.2 outlier checking with Z-score
zOld = (T_clean.old - mean_old) / std_old %[output:8114933c]
zNew = (T_clean.new - mean_new) / std_new %[output:29166741]

flagZOld = abs(zOld) > 3;
flagZNew = abs(zNew) > 3;

disp(T_clean.old(flagZOld));  % null, item valued in 64 is equal to 2.45
disp(T_clean.new(flagZNew));  % null

% 5.3 outlier checking with MAD
[flagMADOld, lowMADOld, highMADOld] = isoutlier(T_clean.old, 'median');
[flagMADNew, lowMADNew, highMADNew] = isoutlier(T_clean.new, 'median');

disp(T_clean.old(flagMADOld));  % null
disp(T_clean.new(flagMADNew));  % null


% 6: visualization of separate figures
% 6.1 values comparison
figure('Name', 'Values by Row', 'NumberTitle', 'off'); %[output:324f8e71]
idx = (1:size(T_clean, 1))';

hold on; %[output:324f8e71]
plot(idx, T_clean.old, '-o', 'LineWidth', 1.5, 'MarkerSize', 5); %[output:324f8e71]
plot(idx, T_clean.new, '-s', 'LineWidth', 1.5, 'MarkerSize', 5); %[output:324f8e71]
hold off; %[output:324f8e71]

xlabel('Row Index'); %[output:324f8e71]
ylabel('Value'); %[output:324f8e71]
title('Old and New: Values by Row'); %[output:324f8e71]
legend('Old', 'New', 'Location', 'best'); %[output:324f8e71]
grid on; %[output:324f8e71]
box on; %[output:324f8e71]

% 6.2 histogram comparison
figure('Name', 'Distribution Comparison', 'NumberTitle', 'off'); %[output:8fc363ff]
[~, binEdges] = histcounts([T_clean.old; T_clean.new], 'BinWidth', 5);

hold on; %[output:8fc363ff]
histogram(T_clean.old, binEdges, 'FaceAlpha', 0.5); %[output:8fc363ff]
histogram(T_clean.new, binEdges, 'FaceAlpha', 0.5); %[output:8fc363ff]
hold off; %[output:8fc363ff]

xlabel('Value'); %[output:8fc363ff]
ylabel('Frequency'); %[output:8fc363ff]
title('Distribution Comparison'); %[output:8fc363ff]
legend('Old', 'New', 'Location', 'best'); %[output:8fc363ff]
grid on; %[output:8fc363ff]
box on; %[output:8fc363ff]

% 6.3 boxplot comparison
figure('Name', 'Boxplot Comparison', 'NumberTitle', 'off'); %[output:1685261d]
boxplot(T_clean{:, :}, 'Labels', {'Old', 'New'}); %[output:1685261d]

ylabel('Value'); %[output:1685261d]
title('Median, Quartiles and Spread'); %[output:1685261d]
grid on; %[output:1685261d]
box on; %[output:1685261d]

% 6.4 summary statistics in the original units
figure('Name', 'Summary Statistics', 'NumberTitle', 'off'); %[output:294f6635]

summaryStats = [
    mean_old, mean_new;
    median_old, median_new;
    std_old, std_new;
    iqr_old, iqr_new;
    range_old, range_new
    ];

bar(summaryStats, 'grouped'); %[output:294f6635]

xticks(1:5); %[output:294f6635]
xticklabels({'Mean', 'Median', 'Std', 'IQR', 'Range'}); %[output:294f6635]
ylabel('Value (original units)'); %[output:294f6635]
title('Summary Statistics: Old vs New'); %[output:294f6635]
legend('Old', 'New', 'Location', 'best'); %[output:294f6635]
grid on; %[output:294f6635]
box on; %[output:294f6635]

% 6.5 percentage change comparison
figure('Name', 'Percentage Change', 'NumberTitle', 'off'); %[output:0cee8d51]

statsOld = [mean_old, median_old, std_old, iqr_old, range_old];
statsNew = [mean_new, median_new, std_new, iqr_new, range_new];

assert(all(statsOld ~= 0), 'Old statistics contain zero values.'); % Avoid division by zero

pctChange = (statsNew - statsOld) ./ statsOld * 100;

b = bar(pctChange, 'FaceColor', 'flat'); %[output:0cee8d51]

colors = zeros(numel(pctChange), 3);
colors(pctChange >= 0, :) = repmat([0 0.4470 0.7410], sum(pctChange >= 0), 1);
colors(pctChange < 0, :) = repmat([0.8500 0.3250 0.0980], sum(pctChange < 0), 1);
b.CData = colors; %[output:0cee8d51]

xticks(1:5); %[output:0cee8d51]
xticklabels({'Mean', 'Median', 'Std', 'IQR', 'Range'}); %[output:0cee8d51]
ylabel('Relative Change (%)'); %[output:0cee8d51]
title('Percentage Change: New vs Old'); %[output:0cee8d51]

yline(0, 'k--', 'LineWidth', 1); %[output:0cee8d51]
ylim([min([pctChange, 0]) - 6, max([pctChange, 0]) + 6]); %[output:0cee8d51]

for i = 1:numel(pctChange)
    label = sprintf('%+.2f%%', pctChange(i));

    if pctChange(i) >= 0
        text(i, pctChange(i) + 1, label, ... %[output:0cee8d51]
            'HorizontalAlignment', 'center', ... %[output:0cee8d51]
            'VerticalAlignment', 'bottom'); %[output:0cee8d51]
    else
        text(i, pctChange(i) - 1, label, ...
            'HorizontalAlignment', 'center', ...
            'VerticalAlignment', 'top');
    end
end

grid on; %[output:0cee8d51]
box on; %[output:0cee8d51]

% 6.6 summary comparison
figure('Name', 'Summary', 'NumberTitle', 'off'); %[output:08c0b130]

sum_old = [min_old, Q1_old, median_old, Q3_old, max_old];
sum_new = [min_new, Q1_new, median_new, Q3_new, max_new];

x = 1:5;

hold on; %[output:08c0b130]
plot(x, sum_old, '-o', 'LineWidth', 2, 'MarkerSize', 8); %[output:08c0b130]
plot(x, sum_new, '-s', 'LineWidth', 2, 'MarkerSize', 8); %[output:08c0b130]
hold off; %[output:08c0b130]

xticks(1:5); %[output:08c0b130]
xticklabels({'Min', 'Q1', 'Median', 'Q3', 'Max'}); %[output:08c0b130]
xlim([0.8, 5.2]); %[output:08c0b130]
ylabel('Value'); %[output:08c0b130]
title('Summary Comparison'); %[output:08c0b130]
legend('Old', 'New', 'Location', 'best'); %[output:08c0b130]
grid on; %[output:08c0b130]
box on; %[output:08c0b130]

% 6.7 coefficient of variation — separate percentage scale
if all([mean_old, mean_new] > 0) %[output:group:9e311a8d]
    cvValues = [std_old, std_new] ./ [mean_old, mean_new] * 100;
    figure('Name', 'Coefficient of Variation', 'NumberTitle', 'off'); %[output:485f678d]

    bar(cvValues); %[output:485f678d]
    xticks([1 2]);   %[output:485f678d]
    xticklabels({'Old', 'New'}); %[output:485f678d]
    ylabel('CV (%)'); %[output:485f678d]
    title('Relative Variability'); %[output:485f678d]
    grid on; %[output:485f678d]
    box on; %[output:485f678d]

    text(1, cvValues(1), sprintf('%.2f%%', cvValues(1)), ... %[output:485f678d]
        'HorizontalAlignment', 'center', ... %[output:485f678d]
        'VerticalAlignment', 'bottom'); %[output:485f678d]
    text(2, cvValues(2), sprintf('%.2f%%', cvValues(2)), ... %[output:485f678d]
        'HorizontalAlignment', 'center', ... %[output:485f678d]
        'VerticalAlignment', 'bottom'); %[output:485f678d]
    ylim([0, max([cvValues, 1]) * 1.2]); %[output:485f678d]

else
    warning('CV plot skipped because a group mean is not positive.');
end %[output:group:9e311a8d]

% 6.8 empirical cumulative distribution comparison 
% (非PPT上内容）

[F_old, x_old] = ecdf(T_clean.old);
[F_new, x_new] = ecdf(T_clean.new);

figure('Name', 'ECDF Comparison', 'NumberTitle', 'off'); %[output:9cefb9bf]

hold on; %[output:9cefb9bf]
stairs(x_old, F_old, '-',  'LineWidth', 1.8); %[output:9cefb9bf]
stairs(x_new, F_new, '--', 'LineWidth', 1.8); %[output:9cefb9bf]
hold off; %[output:9cefb9bf]

xlabel('h');   %[output:9cefb9bf]
ylabel('Cumulative proportion: lifetime <= t'); %[output:9cefb9bf]
title('Empirical Cumulative Distribution'); %[output:9cefb9bf]
legend('Old', 'New', 'Location', 'best'); %[output:9cefb9bf]

ylim([0 1]); %[output:9cefb9bf]
grid on; %[output:9cefb9bf]
box on; %[output:9cefb9bf]

% 6.9 Q-Q plot
figure('Name', 'Normal Q-Q Plots', 'NumberTitle', 'off'); %[output:7d7b9dfb]

subplot(1,2,1); %[output:7d7b9dfb]
qqplot(T_clean.old); %[output:7d7b9dfb]
title('Old: Normal Q-Q Plot'); %[output:7d7b9dfb]
xlabel('Standard Normal Quantiles'); %[output:7d7b9dfb]
ylabel('Sample Quantiles'); %[output:7d7b9dfb]
grid on; %[output:7d7b9dfb]

subplot(1,2,2); %[output:7d7b9dfb]
qqplot(T_clean.new); %[output:7d7b9dfb]
title('New: Normal Q-Q Plot'); %[output:7d7b9dfb]
xlabel('Standard Normal Quantiles'); %[output:7d7b9dfb]
ylabel('Sample Quantiles'); %[output:7d7b9dfb]
grid on; %[output:7d7b9dfb]

% 7: hypothesis testing
% 7.1 normal distribution checking

% [hNormOld, pNormOld] = lillietest(T_clean.old)
% [hNormNew, pNormNew] = lillietest(T_clean.new)  % have warning, p > 0.5

alpha = 0.05;

[hNormOld, pNormOld] = lillietest( ...
    T_clean.old, 'Alpha', alpha, 'MCTol', 0.01);  % Monte Carlo simulation

[hNormNew, pNormNew] = lillietest( ...
    T_clean.new, 'Alpha', alpha, 'MCTol', 0.01);

fprintf('Old: h = %d, p = %.4f\n', hNormOld, pNormOld); %[output:2a672827]
fprintf('New: h = %d, p = %.4f\n', hNormNew, pNormNew); %[output:1ec6a9f1]

% 7.2 Confidence interval
seOld = std_old / sqrt(nOld);
seNew = std_new / sqrt(nNew);

ciOld = mean_old + [-1 1] * tinv(1-alpha/2, nOld-1) * seOld %[output:0dee1c8a]
ciNew = mean_new + [-1 1] * tinv(1-alpha/2, nNew-1) * seNew %[output:956bc17e]

% 7.3 visualization for ci
figure('Name','Mean and 95% CI','NumberTitle','off'); %[output:074aa2fe]
hold on; %[output:074aa2fe]

yOld = 2;
yNew = 1;

line(ciOld, [yOld yOld], 'LineWidth', 8); %[output:074aa2fe]
line(ciNew, [yNew yNew], 'LineWidth', 8); %[output:074aa2fe]

plot(mean_old, yOld, 'o', 'MarkerSize', 18, 'MarkerFaceColor', 'auto'); %[output:074aa2fe]
plot(mean_new, yNew, 'o', 'MarkerSize', 18, 'MarkerFaceColor', 'auto'); %[output:074aa2fe]

yticks([yNew yOld]); %[output:074aa2fe]
yticklabels({'New', 'Old'}); %[output:074aa2fe]

xlabel('Mean lifetime'); %[output:074aa2fe]
title('Group Means with 95% Confidence Intervals'); %[output:074aa2fe]

grid on; %[output:074aa2fe]
box on; %[output:074aa2fe]
ylim([0.5 2.5]); %[output:074aa2fe]

hold off; %[output:074aa2fe]

% 7.4 welch t test
[hWelch, pWelch, ciDiff, stWelch] = ttest2( ...
    T_clean.new, T_clean.old, ...
    'Vartype', 'unequal', ...
    'Tail', 'both', ...
    'Alpha', alpha);

meanDiff = mean_new - mean_old;

fprintf('Mean difference New-Old = %.4f\n', meanDiff); %[output:549614f0]
fprintf('95%% CI = [%.4f, %.4f]\n', ciDiff(1), ciDiff(2)); %[output:273be8f7]
fprintf('t = %.4f, df = %.4f, p = %.4f\n', ... %[output:group:73811d07] %[output:512e843f]
    stWelch.tstat, stWelch.df, pWelch); %[output:group:73811d07] %[output:512e843f]

% 7.5 Visualization of Two-Sided Welch t-Test
tObs = stWelch.tstat;
df = stWelch.df;

tValues = linspace(-4.5, 4.5, 2000);
pdfValues = tpdf(tValues, df);

tCritBoth = tinv(1-alpha/2, df);

figure('Name', 'Two-Sided Welch t-Test', 'NumberTitle', 'off'); %[output:9cfceb2a]

hold on; %[output:9cfceb2a]

leftIdx = tValues <= -abs(tObs);
rightIdx = tValues >= abs(tObs);

patch([tValues(leftIdx), fliplr(tValues(leftIdx))], ... %[output:9cfceb2a]
    [pdfValues(leftIdx), zeros(1,sum(leftIdx))], ... %[output:9cfceb2a]
    [0.8500 0.3250 0.0980], ... %[output:9cfceb2a]
    'FaceAlpha', 0.4, 'EdgeColor', 'none'); %[output:9cfceb2a]

patch([tValues(rightIdx), fliplr(tValues(rightIdx))], ... %[output:9cfceb2a]
    [pdfValues(rightIdx), zeros(1,sum(rightIdx))], ... %[output:9cfceb2a]
    [0.8500 0.3250 0.0980], ... %[output:9cfceb2a]
    'FaceAlpha', 0.4, 'EdgeColor', 'none'); %[output:9cfceb2a]

plot(tValues, pdfValues, 'LineWidth', 2, 'Color', [0 0.4470 0.7410]); %[output:9cfceb2a]

xline(-abs(tObs), 'k--'); %[output:9cfceb2a]
xline(abs(tObs), 'k--'); %[output:9cfceb2a]

xline(-tCritBoth, 'r:'); %[output:9cfceb2a]
xline(tCritBoth, 'r:'); %[output:9cfceb2a]

xlabel('t Statistic'); %[output:9cfceb2a]
ylabel('Probability Density'); %[output:9cfceb2a]

title(sprintf('Two-Sided Welch t-Test (p = %.4f)', pWelch)); %[output:9cfceb2a]

grid on; %[output:9cfceb2a]
box on; %[output:9cfceb2a]
hold off; %[output:9cfceb2a]

% 7.6 Welch Two-Sample t-Test
[~, pRight] = ttest2(T_clean.new, T_clean.old, 'Vartype', 'unequal', 'Tail', 'right') %[output:1f7bc09e]

% 7.7 Visualization of Right-Tailed Welch t-Test
tCritRight = tinv(1-alpha, df);

figure('Name', 'Right-Tailed Welch t-Test', 'NumberTitle', 'off'); %[output:61e2886e]
hold on; %[output:61e2886e]

rightIdx = tValues >= tObs;

patch([tValues(rightIdx), fliplr(tValues(rightIdx))], ... %[output:61e2886e]
    [pdfValues(rightIdx), zeros(1,sum(rightIdx))], ... %[output:61e2886e]
    [0.8500 0.3250 0.0980], ... %[output:61e2886e]
    'FaceAlpha', 0.4, 'EdgeColor', 'none'); %[output:61e2886e]

plot(tValues, pdfValues, ... %[output:61e2886e]
    'LineWidth', 2, 'Color', [0 0.4470 0.7410]); %[output:61e2886e]

xline(tObs, 'k--', 'Observed t'); %[output:61e2886e]
xline(tCritRight, 'r:', 'Critical t'); %[output:61e2886e]

xlabel('t Statistic'); %[output:61e2886e]
ylabel('Probability Density'); %[output:61e2886e]

title(sprintf('Right-Tailed Welch t-Test (p = %.4f)', pRight)); %[output:61e2886e]

grid on; %[output:61e2886e]
box on; %[output:61e2886e]
hold off; %[output:61e2886e]

% 7.8 Two-sample F-test for variances
[hVar, pVar, ciVarRatio, stVar] = vartest2( ...
    T_clean.new, T_clean.old, ...
    'Tail', 'both', 'Alpha', alpha);

fprintf('Variance ratio New/Old = %.4f\n', var(T_clean.new,0) / var(T_clean.old,0)); %[output:56fb0dc0]
fprintf('F = %.4f, p = %.4f\n', stVar.fstat, pVar); %[output:29ab1d0d]
fprintf('95%% CI for variance ratio = [%.4f, %.4f]\n', ciVarRatio(1), ciVarRatio(2)); %[output:35848db9]

if hVar %[output:group:752757ad]
    fprintf('Evidence of different population variances.\n');
else
    fprintf('Insufficient evidence of different population variances.\n'); %[output:9ff33a08]
end %[output:group:752757ad]

% 7.9 visualization of Two-Sample F-Test

% Calculate critical F values
fCritLower = finv(alpha/2, stVar.df1, stVar.df2);
fCritUpper = finv(1-alpha/2, stVar.df1, stVar.df2);

fMax = max([finv(0.999, stVar.df1, stVar.df2), ...  % Generate F-distribution curve
    1.2*stVar.fstat, 1.1*fCritUpper]);

fValues = linspace(0, fMax, 3000);
pdfValues = fpdf(fValues, stVar.df1, stVar.df2);

figure('Name', 'Two-Sample F-Test', ... %[output:6fc203b0]
    'NumberTitle', 'off'); %[output:6fc203b0]

hold on; %[output:6fc203b0]

% Left rejection region
leftIdx = fValues <= fCritLower;

hLeft = patch( ... %[output:6fc203b0]
    [fValues(leftIdx), fliplr(fValues(leftIdx))], ... %[output:6fc203b0]
    [pdfValues(leftIdx), zeros(1, sum(leftIdx))], ... %[output:6fc203b0]
    [0.8500 0.3250 0.0980], ... %[output:6fc203b0]
    'FaceAlpha', 0.4, ... %[output:6fc203b0]
    'EdgeColor', 'none'); %[output:6fc203b0]

% Right rejection region
rightIdx = fValues >= fCritUpper;

patch( ... %[output:6fc203b0]
    [fValues(rightIdx), fliplr(fValues(rightIdx))], ... %[output:6fc203b0]
    [pdfValues(rightIdx), zeros(1, sum(rightIdx))], ... %[output:6fc203b0]
    [0.8500 0.3250 0.0980], ... %[output:6fc203b0]
    'FaceAlpha', 0.4, ... %[output:6fc203b0]
    'EdgeColor', 'none'); %[output:6fc203b0]

% F probability density
hPDF = plot(fValues, pdfValues, ... %[output:6fc203b0]
    'LineWidth', 2, ... %[output:6fc203b0]
    'Color', [0 0.4470 0.7410]); %[output:6fc203b0]

% Observed F statistic
xline(stVar.fstat, 'k--', 'Observed F', 'LineWidth', 1.5); %[output:6fc203b0]

% Critical F values
xline(fCritLower, 'r:', 'Lower Critical'); %[output:6fc203b0]
xline(fCritUpper, 'r:', 'Upper Critical'); %[output:6fc203b0]

xlabel('F Statistic (New Variance / Old Variance)'); %[output:6fc203b0]
ylabel('Probability Density'); %[output:6fc203b0]

title(sprintf('Two-Sided F-Test (p = %.4f)', pVar)); %[output:6fc203b0]

legend([hPDF, hLeft], ... %[output:6fc203b0]
    {'F Distribution', 'Rejection Regions'}, ... %[output:6fc203b0]
    'Location', 'northeast'); %[output:6fc203b0]

xlim([0 fMax]); %[output:6fc203b0]

grid on; %[output:6fc203b0]
box on; %[output:6fc203b0]
hold off; %[output:6fc203b0]

% 7.10 Visualization for Variance Ratio 95% CI

figure('Name', 'Variance Ratio Confidence Interval', ... %[output:820db19b]
    'NumberTitle', 'off'); %[output:820db19b]

hold on; %[output:820db19b]

% Confidence interval
plot([ciVarRatio(1), ciVarRatio(2)], [1, 1], ... %[output:820db19b]
    '-', 'LineWidth', 5, 'Color', [0 0.4470 0.7410]); %[output:820db19b]

% CI endpoints
plot(ciVarRatio, [1, 1], '|', 'MarkerSize', 16, ... %[output:820db19b]
    'LineWidth', 2, 'Color', [0 0.4470 0.7410]); %[output:820db19b]

% Observed variance ratio
plot(stVar.fstat, 1, 'o', 'MarkerSize', 12, ... %[output:820db19b]
    'MarkerFaceColor', [0 0.4470 0.7410], ... %[output:820db19b]
    'MarkerEdgeColor', [0 0.4470 0.7410]); %[output:820db19b]

hold off; %[output:820db19b]

% Equal variance reference
xline(1, 'r--', 'Equal Variances (Ratio = 1)'); %[output:820db19b]
yticks(1); %[output:820db19b]
yticklabels({'New / Old'}); %[output:820db19b]
ylim([0.75, 1.25]); %[output:820db19b]

xlim([0, max([ciVarRatio(:); 1; stVar.fstat]) * 1.15]); %[output:820db19b]

xlabel('Population Variance Ratio'); %[output:820db19b]
title(sprintf('Variance Ratio: %.3f (95%% CI: %.3f to %.3f)', ... %[output:820db19b]
    stVar.fstat, ciVarRatio(1), ciVarRatio(2))); %[output:820db19b]

grid on; %[output:820db19b]
box on; %[output:820db19b]


% 8: binomial distribution
% 8.1 binomial distribution
threshold = 40;  % just an example
successOld = sum(T_clean.old >= threshold);
successNew = sum(T_clean.new >= threshold);

pOld = successOld / nOld;
pNew = successNew / nNew;

fprintf('Old: %d/%d = %.2f%%\n', successOld, nOld, pOld * 100); %[output:585071f5]
fprintf('New: %d/%d = %.2f%%\n', successNew, nNew, pNew * 100); %[output:060b3292]

contingencyTable = [
    successNew, nNew - successNew;
    successOld, nOld - successOld
    ];

[hFisher, pFisher] = fishertest( ...
    contingencyTable, ...
    'Tail', 'right', ...
    'Alpha', alpha);

fprintf('Fisher exact test: h = %d, p = %.4f\n', hFisher, pFisher); %[output:8b720438]

% 8.2 visualization for binomial distribution
k = 0:20;
probOld = binopdf(k, nOld, pOld);
probNew = binopdf(k, nNew, pNew);

figure('Name', 'Binomial Distribution', ... %[output:302d8449]
    'NumberTitle', 'off'); %[output:302d8449]

bar(k, [probOld(:), probNew(:)], 'grouped'); %[output:302d8449]

xlabel('Number of Successful Resistors (k)'); %[output:302d8449]
ylabel('Probability P(K = k)'); %[output:302d8449]
title('Estimated Binomial Distributions'); %[output:302d8449]

legend('Old', 'New', 'Location', 'best'); %[output:302d8449]
xticks(0:2:20); %[output:302d8449]

grid on; %[output:302d8449]
box on; %[output:302d8449]

% 8.3 ci for binomial distribution
[pBinOld, ciBinOld] = binofit(successOld, nOld, alpha);
[pBinNew, ciBinNew] = binofit(successNew, nNew, alpha);

fprintf('Old survival: %.2f%%, 95%% CI [%.2f%%, %.2f%%]\n', ... %[output:group:8c8e79c2] %[output:6fde4f0e]
    pBinOld*100, ciBinOld(1)*100, ciBinOld(2)*100); %[output:group:8c8e79c2] %[output:6fde4f0e]
fprintf('New survival: %.2f%%, 95%% CI [%.2f%%, %.2f%%]\n', ... %[output:group:5d87e0aa] %[output:7723615c]
    pBinNew*100, ciBinNew(1)*100, ciBinNew(2)*100); %[output:group:5d87e0aa] %[output:7723615c]

% 8.4 visualization for ci of binomial distribution
figure('Name', 'Survival Probability 95% CI', 'NumberTitle', 'off'); %[output:1ee054f2]

pBinValues = [pBinOld; pBinNew] * 100;
ciBinValues = [ciBinOld; ciBinNew] * 100;

lowerError = pBinValues - ciBinValues(:,1);  % Error lengths
upperError = ciBinValues(:,2) - pBinValues;

% Draw bars
hold on; %[output:1ee054f2]

b = bar(1:2, pBinValues, 0.55, 'FaceColor', 'flat'); %[output:1ee054f2]
b.CData = [ %[output:1ee054f2]
    0    0.4470 0.7410; %[output:1ee054f2]
    0.8500 0.3250 0.0980 %[output:1ee054f2]
    ]; %[output:1ee054f2]

% Draw asymmetric 95% confidence intervals
errorbar(1:2, pBinValues, lowerError, upperError, ... %[output:1ee054f2]
    'k.', 'LineWidth', 1.8, 'CapSize', 12); %[output:1ee054f2]

hold off; %[output:1ee054f2]

xticks(1:2); %[output:1ee054f2]
xticklabels({'Old', 'New'}); %[output:1ee054f2]

ylabel('Survival Probability (%)'); %[output:1ee054f2]
title('Survival Probability with 95% CI'); %[output:1ee054f2]

ylim([0 100]); %[output:1ee054f2]
grid on; %[output:1ee054f2]
box on; %[output:1ee054f2]


% 9: normality and homogeneity
% 9.1 Brown–Forsythe test (课件上没有）
[pBF, stBF] = vartestn( ...
    T_clean{:, {'old','new'}}, ...
    'TestType', 'BrownForsythe', ...
    'Display', 'off');

fprintf('Brown-Forsythe: F = %.4f, p = %.4f\n', ... %[output:group:0ec83a9e] %[output:0a5fe958]
    stBF.fstat, pBF); %[output:group:0ec83a9e] %[output:0a5fe958]

if pBF < alpha %[output:group:772aa4ba]
    fprintf('Evidence of unequal variances.\n');
else
    fprintf('Insufficient evidence of unequal variances.\n'); %[output:7cc7d84d]
end %[output:group:772aa4ba]

% 9.2 Levene test
[pLevene, stLevene] = vartestn( ...
    T_clean{:, {'old','new'}}, ...
    'TestType', 'LeveneAbsolute', ...
    'Display', 'off');

fprintf('Levene: F = %.4f, p = %.4f\n', ... %[output:group:32fc025b] %[output:0e98a5ba]
    stLevene.fstat, pLevene); %[output:group:32fc025b] %[output:0e98a5ba]

% 9.3 One-way ANOVA
[pAnova, anovaTable, stAnova] = anova1( ...
    T_clean{:, {'old','new'}}, ...
    {'Old','New'}, 'off');

disp(anovaTable); %[output:803890d4]

fprintf('One-way ANOVA: F = %.4f, p = %.4f\n', anovaTable{2,5}, pAnova); %[output:8ccdae04]

if pAnova < alpha %[output:group:9aa6f8ec]
    fprintf('Evidence of different population means.\n');
else
    fprintf('Insufficient evidence of different population means.\n'); %[output:4effc5c8]
end %[output:group:9aa6f8ec]

% 9.4 non-parameter test (rank-sum, 课件上没有)
[pRank, hRank, stRank] = ranksum( ...
    T_clean.new, T_clean.old, ...
    'Tail', 'both', 'Alpha', alpha, ...
    'Method', 'approximate');

fprintf('Rank-sum: z = %.4f, p = %.4f\n', stRank.zval, pRank); %[output:0852401f]


% 10: sensitivity analysis
[~, pFull, ciFull] = ttest2( ...
    T_clean.new, T_clean.old, ...
    'Vartype', 'unequal', ...
    'Tail', 'both', ...
    'Alpha', alpha);

idx64 = find(T_clean.old == 64, 1);

if ~isempty(idx64) %[output:group:857b022b]
    oldSensitivity = T_clean.old;
    oldSensitivity(idx64) = [];

    [~, pSensitivity, ciSensitivity] = ttest2( ...
        T_clean.new, oldSensitivity, ...
        'Vartype', 'unequal', ...
        'Tail', 'both', ...
        'Alpha', alpha);

    sensitivityTable = table( ...
        {'All observations'; 'Temporarily omit old 64'}, ...
        [numel(T_clean.old); numel(oldSensitivity)], ...
        [mean(T_clean.new)-mean(T_clean.old); ...
        mean(T_clean.new)-mean(oldSensitivity)], ...
        [ciFull(1); ciSensitivity(1)], ...
        [ciFull(2); ciSensitivity(2)], ...
        [pFull; pSensitivity], ...
        'VariableNames', ...
        {'Analysis','OldN','MeanDifference', ...
        'CILower','CIUpper','PValue'});

    disp(sensitivityTable); %[output:4e847b54]

else
    fprintf('Old value 64 was not found; sensitivity analysis skipped.\n');
end %[output:group:857b022b]






